// Функция проверки приблизительного равенства с погрешностью 0.5%
function pribliz(a, b, proc) {
  const min = b - (b / 100 * proc);
  const max = b + (b / 100 * proc);
  return a > min && a < max;
}

// Получаем данные сигнала из предыдущего узла n8n
const signal = $('Формирование метаданных запроса4').first().json

// Получаем свечи (массив из HTTP запроса к Binance)
const candles = $input.all().map(item => item.json);

let startSignal = false;
let result = null;
let entryPrice = null; // Добавляем переменную для хранения цены входа

// Проходим по всем свечам
for (const candle of candles) {
  const price = parseFloat(candle[1]); // Цена закрытия свечи

  // Проверяем вход в позицию
  if (!startSignal) {
    if (pribliz(price, parseFloat(signal.entry_point), 0.5)) {
      startSignal = true;
      entryPrice = price; // Запоминаем цену фактического входа
    }
    continue; // Пропускаем проверку стопа, пока не вошли
  }

  // Активная позиция - проверяем стоп и тейк-профит
  if (signal.direction === "long") {
    if (price <= parseFloat(signal.stop_point)) {
      const percentChange = ((signal.stop_point - entryPrice) / entryPrice) * 100;
      result = {
        status: "stop_loss",
        exit_price: price,
        percent: percentChange.toFixed(2),
        message: `❌ Сработал стоп-лосс (${percentChange.toFixed(2)}%)`
      };
      break;
    }
    if (price >= parseFloat(signal.profit_point)) {
      const percentChange = ((signal.profit_point - entryPrice) / entryPrice) * 100;
      result = {
        status: "take_profit",
        exit_price: price,
        percent: percentChange.toFixed(2),
        message: `✅ Сработал тейк-профит (+${percentChange.toFixed(2)}%)`
      };
      break;
    }
  } 
  else if (signal.direction === "short") {
    if (price >= parseFloat(signal.stop_point)) {
      const percentChange = ((entryPrice - signal.stop_point) / entryPrice) * 100;
      result = {
        status: "stop_loss",
        exit_price: price,
        percent: percentChange.toFixed(2),
        message: `❌ Сработал стоп-лосс (-${percentChange.toFixed(2)}%)`
      };
      break;
    }
    if (price <= parseFloat(signal.profit_point)) {
      const percentChange = ((entryPrice - signal.profit_point) / entryPrice) * 100;
      result = {
        status: "take_profit",
        exit_price: price,
        percent: percentChange.toFixed(2),
        message: `✅ Сработал тейк-профит (+${percentChange.toFixed(2)}%)`
      };
      break;
    }
  }
}

// Если ни стоп, ни профит не сработали за период
if (!result) {
  result = {
    status: "no_exit",
    exit_price: null,
    percent: null,
    message: "⏸️ Не сработало ни стопа, ни профита за неделю"
  };
}

// Возвращаем результат с исходными данными сигнала
return {
  ticker: signal.ticker,
  direction: signal.direction,
  signal_date: signal.date,
  entry_point: signal.entry_point,
  actual_entry_price: entryPrice, // фактическая цена входа
  stop_point: signal.stop_point,
  profit_point: signal.profit_point,
  result_status: result.status,
  exit_price: result.exit_price,
  percent: result.percent,
  message: result.message
};

let prompt = `
You are a crypto signal classifier based on TradingView chart screenshots.

Your task: analyze the chart image and return ONLY valid JSON. No explanatory text, just JSON.

## Categories (similar to rules):
- "Signal" — the chart has a clear entry point (arrow, line, "Entry" label, horizontal line with price).

- "Result" — the chart shows a closed trade, take profit, or stop loss.

- "Announcement" — the chart text announces a future signal, suggesting a wait.

- "Noise" — a general market overview without a specific entry point.

## Confidence:
- 0.9–1.0: There is an entry line + price + arrow + direction + clearly defined time.

- 0.7–0.8: There is an entry line, but no arrow or direction; the time is approximate.

- 0.5–0.6: There is a line, but no price on the chart, the time is unclear.

- Below 0.5: the signal is unreadable.

## Direction:
- If the arrow points up, the text "BUY" / "BUY LONG" is present — a long position.

- If the arrow points down, the text "SELL" / "BUY SHORT" is present — a short position.

## How to determine the entry point on the chart (basic rule):
**entry_point is a horizontal line (level) on the TradingView chart with a price label to the right.**
- If you see a horizontal dotted or solid line and a numeric label to the right of it (e.g., "0.3456" or "Entry 1.2345"), this is the entry point.
- An arrow pointing from the price to the line is confirmation.
- If there is only one line, this is the entry point. If there are multiple lines (for example, the entry zone from and to), take the average value or the value labeled "Entry."
entry_point - required field

## Signal Start Time
start_time is the time on the lower TradingView axis corresponding to the start point of the arrow.
Algorithm:
1. Find the start of the arrow (tail) or the leftmost point of the trendline.
2. Move vertically down to the time axis.
3. Calculate the time at this point on the axis, even if there is no candle there.
Tips for determining start_time:
1. Look at the entire time axis; numbers without : denote dates, and with : denote the time to that date.
2. Carefully examine the dates in the image; if you see something like 12/6/2026, this is the starting point for determining start_time.
3. Important!!! start_time - not the chart start time, but the price arrow start time.
4. It's possible that the date and time haven't arrived yet - this is normal.

If the start point is between time labels:
- Interpolate visually: exactly in the middle → average time, closer to the left label → +25-30% of the interval.
- Example: between 12:00 and 1:30 PM, in the middle → 12:45.
start_time: Unix timestamp in milliseconds or null.
start_time - required field.

## How to determine other prices:
- Stop loss (stop loss trigger level) is a horizontal line below the entry point for a long position and above it for a short position. Usually marked as "SL," "Stop," or "Stop Loss."

The take-profit level is a horizontal line above the entry point for a long position and below it for a short position. It is designated as "TP," "Take Profit," or "Target." If not explicitly specified (there is no TP or take-profit in the text or on the chart), the value is null.

- Time - signal duration. If Take-profit is not specified, the signal time must be specified (15 minutes, 1 hour, etc.).

## Output format (strict):
{
"category": "signal | result | announcement | noise",
"is_signal": true/false,
"ticker": "BTCUSDT or null",
"direction": "long | short | null",
"confidence": a number from 0 to 1,
"time": a number (milliseconds) or null,
"entry_point": a number or null,
"stop_point": a number or null,
"profit_point": a number or null,
"start_time": the start time of the price movement in milliseconds. Note that it is important to specify not only the time but also the date.
}

## Important limitations:
- Do not generate prices if there is no horizontal line.

- Line priority: Entry → TP → SL.
— The signal time is the moment when a position should be opened, not the time the screenshot is taken.`;

