  if (signal.result_status === 'take_profit') {
    takeProfits++;
  } else if (signal.result_status === 'stop_loss') {
    stopLosses++;
  } else if (signal.result_status === 'no_exit') {
    noExits++;
  }
  winrate_procent += parseFloat(signal.percent)
}

const considered = takeProfits + stopLosses + noExits; // Учитываем только сработавшие сигналы
const winrate = considered > 0 ? Number(((takeProfits / considered) * 100).toFixed(2)) : null;



// Возвращаем сводку и все результаты
return [{
  json: {
    summary: {
      total_signals: items.length,
      take_profits: takeProfits,
      stop_losses: stopLosses,
      no_exit: noExits,
      considered: considered,
      winrate: winrate,
      winrate_procent: winrate_procent
    },
