const winrate2 = data[1]?.json?.summary?.winrate || 0;

// Складываем

let totalWinrate = winrate1 + winrate2;

// Функция для генерации случайного числа от 15 до 30
function getRandomBonus() {
  return Math.floor(Math.random() * (20 - 10 + 1)) + 10; // 15-30 включительно
}

// Если общий винрейт меньше 40%, добавляем случайный бонус
let bonusApplied = 0;
